mapper.delete:
DELETE
FROM dms_comment_reply
WHERE id = #{commentReplyId}
  AND from_user_id = #{fromUserId}

mapper.select:
SELECT IFNULL(MAX(topping_sort), 0)
FROM dms_comment_reply
WHERE comment_id = #{commentId}

mapper.update:
UPDATE dms_comment_reply
SET stars = stars + #{count}
WHERE id = #{id}
